package com.globalhire.controller;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/reports")public class ReportController{@PostMapping("/generate")public Map<String,Object> gen(@RequestBody Map<String,Object>b){return Map.of("title",b.getOrDefault("title","Global hiring decision report"),"summary","Report generated from the supplied hiring requirements. It includes country trade-offs, estimated cost, talent context, predicted outcomes and compliance notes. Verify demo data before operational use.","generatedAt",new Date().toString(),"countries",b.getOrDefault("countries",List.of()));}}